export const getReplaceSubjectUrl = (id: number) => {
  return `/api/subjects/${id}`;
};

/**
 * Uses the same body and defaults as create. Omitted optional fields are cleared.
 * `lecturers` is accepted but ignored: lecturers can only be set when the subject is created.
 * @summary Replace a subject by ID
 */
export const replaceSubject = async (
  id: number,
  subjectCreateRequest: SubjectCreateRequest,
  options?: Parameters<typeof fetcher>[1],
): Promise<Subject> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return fetcher<Subject>(getReplaceSubjectUrl(id), {
    ...options,
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(subjectCreateRequest),
  });
};

